# The transformation rule!
def transform(grid):
    """Transform the input grid by creating a 2x2 arrangement of rotations."""
    n = len(grid)
    result = [[0] * (2 * n) for _ in range(2 * n)]

    # TL: input as-is
    for i in range(n):
        for j in range(n):
            result[i][j] = grid[i][j]

    # TR: rotate 90 degrees clockwise
    # TR[i][j] = input[n-1-j][i]
    for i in range(n):
        for j in range(n):
            result[i][j + n] = grid[n - 1 - j][i]

    # BL: rotate 90 degrees counter-clockwise (270 CW)
    # BL[i][j] = input[j][n-1-i]
    for i in range(n):
        for j in range(n):
            result[n + i][j] = grid[j][n - 1 - i]

    # BR: rotate 180 degrees
    # BR[i][j] = input[n-1-i][n-1-j]
    for i in range(n):
        for j in range(n):
            result[n + i][n + j] = grid[n - 1 - i][n - 1 - j]

    return result

